            e["logits"] = np.array(s["original"]["label_logits"][wi]); e["last"] = wi == 1; e["id"] = s["id"]
            if name.startswith("h"):
                e.update({"pair": m["pair"], "feat": m["feat"], "sign": m["sign"]})
