            if t == n - 1:
                W.append({"sid": s["id"], "set": setname, "feat": m.get("feat"), "sign": m.get("sign"), "pair": m.get("pair"), "group": m.get("group"), "tag": m.get("tag"), **{k: v[wi] for k, v in sp.items()}})


for c in (5, 6, 7, 8):
